let stationeryFonts;export function ensureStationeryFonts(){return Promise.all([ensureOrnamentArtwork(),stationeryFonts??=Promise.all([document.fonts.load('500 32px Fraunces'),document.fonts.load('700 32px Fraunces'),document.fonts.load('400 18px Nunito'),document.fonts.load('700 18px Nunito'),document.fonts.load('800 18px Nunito')]).catch(()=>{})]);}
export const stationeryLayouts={editorial:'Encontro editorial',lembranca:'Moldura de afeto',colagem:'Mural de histórias',jornal:'Jornal de memórias',faixa:'Faixa fotográfica',poster:'Retrato de capa',dupla:'Duas lembranças',carta:'Carta de coleção',arquivo:'Arquivo afetivo',janela:'Janela de encontro'};
export function cleanStationery(value={}){const v=value&&typeof value==='object'?value:{};return {layout:Object.hasOwn(stationeryLayouts,v.layout)?v.layout:'editorial',title:String(v.title||'').slice(0,90),photoNote:String(v.photoNote||'').slice(0,80),closing:String(v.closing||'').slice(0,120),fit:v.fit==='cover'?'cover':'contain',seal:v.seal!==false};}
