 const imageList=[photo,...photos.filter(image=>image&&image!==photo)].filter(Boolean);const initials=name.split(/\s+(?:e|&)\s+|\s+/).filter(word=>word.length>1).slice(0,2).map(word=>Array.from(word)[0]).join(' · ').toLocaleUpperCase('pt-BR');
