  if(appearance.showLabels)paintLabel(ctx,data.theme?.label||'um carinho para você',443,56,Math.min(300,320),29,labelColors(data));write(ctx,design.title||'Um carinho\nque fica.',443,130,320,48,{align:'left',lines:3,weight:700});rule(445,328,48);write(ctx,'Para '+name,443,363,320,27,{align:'left',lines:2});write(ctx,closing,443,484,315,17,{align:'left',lines:3,color:accent});
