export function initStationeryEditor({getState,onChange}){
 const panel=document.createElement('section');panel.className='stationery-editor';panel.innerHTML='<h3>Um presente com a sua cara.</h3><p>Escolha a composição. Sua foto e suas palavras entram no próprio desenho do cartão, convite ou livro.</p><div class="stationery-layouts" role="group" aria-label="Composição do cartão ou convite"></div><div class="field"><label for="stationery-title">Título da capa</label><input id="stationery-title" maxlength="90" placeholder="Ex.: Um carinho só seu."></div><div class="field"><label for="stationery-note">Legenda da moldura</label><input id="stationery-note" maxlength="80" placeholder="Ex.: Nosso lugar favorito é juntos."></div><div class="field"><label for="stationery-closing">Assinatura ou fechamento</label><input id="stationery-closing" maxlength="120" placeholder="Ex.: Com todo o meu amor, Rafa."></div><div class="field"><label for="stationery-fit">Como a foto entra na moldura?</label><select id="stationery-fit"><option value="contain">Foto inteira, sem corte</option><option value="cover">Preencher a moldura</option></select></div><label class="stationery-seal"><input type="checkbox" id="stationery-seal" checked> Incluir selo ilustrado</label><p class="stationery-art-note">A prévia 3D, as imagens baixadas e o arquivo de quem recebe usam o mesmo desenho.</p>';
 document.querySelector('.character-field').before(panel);const patch=value=>onChange({stationeryDesign:cleanStationery({...getState().stationeryDesign,...value})});for(const [key,label] of Object.entries(stationeryLayouts)){const button=document.createElement('button');button.type='button';button.dataset.stationeryLayout=key;button.className='stationery-layout '+key;const motif=document.createElement('span');motif.className='stationery-layout-mini';motif.setAttribute('aria-hidden','true');const text=document.createElement('strong');text.textContent=label;button.append(motif,text);button.addEventListener('click',()=>patch({layout:key}));panel.querySelector('.stationery-layouts').append(button);}for(const [id,key] of [['stationery-title','title'],['stationery-note','photoNote'],['stationery-closing','closing'],['stationery-fit','fit']])panel.querySelector('#'+id).addEventListener('input',event=>patch({[key]:event.target.value}));panel.querySelector('#stationery-seal').addEventListener('change',event=>onChange({stationeryDesign:cleanStationery({...getState().stationeryDesign,seal:event.target.checked}),...(event.target.checked&&getState().character==='none'?{character:'capy'}:{})}));
 function render(){panel.hidden=getState().format==='stories';const value=cleanStationery(getState().stationeryDesign);for(const [id,key] of [['stationery-title','title'],['stationery-note','photoNote'],['stationery-closing','closing'],['stationery-fit','fit']]){const input=panel.querySelector('#'+id);if(input!==document.activeElement)input.value=value[key];}panel.querySelector('#stationery-seal').checked=value.seal&&getState().character!=='none';panel.querySelectorAll('[data-stationery-layout]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.stationeryLayout===value.layout)));}render();return {render};
}
